//! Official Searcher behavior; no manual D-Reaper trait injection into Searcher.
use digimon_engine::action::{build_action_mask,space::{PLAY_HAND_START,encode_attack}};
use digimon_engine::debug_runner::{DebugRunner,make_test_card};
use digimon_engine::enums::{GamePhase,CostDelta,PlaySource};
fn setup(actor:u8)->DebugRunner{
 let path=std::env::var_os("EX2_046_CANDIDATE_YAML").map(std::path::PathBuf::from).unwrap_or_else(||std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("cards/ex2/EX2-046.yaml"));
 let mut yaml=std::fs::read_to_string(path).unwrap();if std::env::var_os("EX2_046_BASELINE").is_some(){yaml=yaml.split("effects:").next().unwrap().into();}
 let mut r=DebugRunner::builder().from_dsl_yaml(&yaml).unwrap().add_card(make_test_card("SEARCH-FILL","Plain witness")).deck(0,&["SEARCH-FILL";30]).deck(1,&["SEARCH-FILL";30]).memory(10).start();r.skip_mulligan();r.set_first_player(actor);r.game.current_phase=GamePhase::Main;r
}
fn native(r:&mut DebugRunner,actor:u8){let i=r.add_to_hand(actor,"EX2-046");let a=PLAY_HAND_START+i as u16;assert!(build_action_mask(&r.game,actor)[a as usize]>0.0);r.game.decode_action(a,actor);assert!(r.pending_selection_view().is_none(),"mandatory reducer/draw must not manufacture a choice");}
#[test]
fn first_hand_play_costs_one_second_costs_three_and_each_draws_once(){for actor in [0,1]{let mut r=setup(actor);let hand=r.hand_size(actor);native(&mut r,actor);assert_eq!(r.game.memory,9);assert_eq!(r.hand_size(actor),hand+1);native(&mut r,actor);assert_eq!(r.game.memory,6);assert_eq!(r.hand_size(actor),hand+2);assert_eq!(r.battle_area_size(actor),2);}}
#[test]
fn opponent_and_breeding_searchers_do_not_block_first_play_reduction(){for actor in [0,1]{let mut r=setup(actor);r.place_on_field(1-actor,"EX2-046",None);r.place_in_breeding(actor,"EX2-046");let snap=r.game.clone();for cloned in [false,true]{r.game=snap.clone();if cloned{r.game=r.game.clone();}native(&mut r,actor);assert_eq!(r.game.memory,9);}}}
#[test]
fn effect_play_preserves_physical_hand_origin_and_free_play_cost(){for actor in [0,1]{for origin in ["hand","trash","free"]{let mut r=setup(actor);let hand=r.hand_size(actor);let expected=match origin{"hand"=>{let i=r.add_to_hand(actor,"EX2-046");assert!(r.game.play_from_hand_with_cost(actor,i,CostDelta::Reduce(0),PlaySource::ByEffect).is_some());9},"trash"=>{r.inject_trash(actor,"EX2-046");assert!(r.game.play_from_trash(actor,0).is_some());7},_=>{r.inject_trash(actor,"EX2-046");assert!(r.game.play_from_trash_with_cost(actor,0,CostDelta::Free,PlaySource::ByEffect).is_some());10}};r.game.drain_effect_queue();assert_eq!(r.game.memory,expected,"{origin}");assert_eq!(r.hand_size(actor),hand+1);assert_eq!(r.battle_area_size(actor),1);}}}
#[test]
fn player_attack_is_masked_but_suspended_digimon_attack_remains_legal(){for actor in [0,1]{let mut r=setup(actor);r.place_on_field(actor,"EX2-046",Some(0));r.game.turn_count=2;let opp=r.place_on_field(1-actor,"SEARCH-FILL",Some(0));r.game.player_mut(opp.player).battle_area[opp.index as usize].is_suspended=true;r.game.tick_declarative_effects();let m=build_action_mask(&r.game,actor);assert_eq!(m[encode_attack(0,14) as usize],0.0);assert!(m[encode_attack(0,0) as usize]>0.0);}}
#[test]
fn inherited_aura_uses_printed_form_stacks_and_expires_with_source_and_turn(){for actor in [0,1]{let mut r=setup(actor);let data=r.game.card_data.iter().find(|x|x.card_id=="EX2-046").unwrap();assert_eq!(data.level,None);assert!(data.traits.iter().any(|s|s=="D-Reaper"));assert!(data.traits.iter().any(|s|s=="Intel Acquisition Agent"));let host=r.place_stack(actor,&["EX2-046","EX2-046","EX2-046"]);let own=r.place_on_field(actor,"EX2-046",None);let plain=r.place_on_field(actor,"SEARCH-FILL",None);let opp=r.place_on_field(1-actor,"EX2-046",None);let plain_base=r.effective_dp(plain);r.game.tick_declarative_effects();assert_eq!(r.effective_dp(host),Some(3000));assert_eq!(r.effective_dp(own),Some(3000));assert_eq!(r.effective_dp(opp),Some(1000));assert_eq!(r.effective_dp(plain),plain_base);let snap=r.game.clone();for clone in [false,true]{r.game=snap.clone();if clone{r.game=r.game.clone();}r.set_first_player(1-actor);r.game.tick_declarative_effects();assert_eq!(r.effective_dp(host),Some(1000));assert_eq!(r.effective_dp(own),Some(1000));}r.game=snap;r.game.delete_permanent_with_effects(host);r.game.tick_declarative_effects();assert_eq!(r.effective_dp(digimon_engine::permanent::PermanentHandle{player:actor,index:0}),Some(1000));}}
#[test]
fn official_fifty_copy_rule_is_available_to_real_deck_validation(){assert_eq!(digimon_engine::deck_tools::card_database()["EX2-046"].max_count_in_deck,50);let ids=vec!["EX2-046".to_string();50];let result=digimon_engine::deck_tools::validate_deck(&ids);assert!(result.errors.is_empty(),"{result:?}");}
